#!/usr/bin/env node
/**
 * Produce every generated API artifact. Feature PRs never commit these
 * (owner directive 2026-11-19, AGENTS.md "Generated files"): they are
 * gitignored build outputs, generated by CI, the production deploy workflow
 * and local development from the Rust declarations.
 *
 * 1. `cargo run --example api_contracts` writes the Rust-generated contracts
 *    (`comicpile_roll_service::contract_artifacts::CONTRACT_ARTIFACTS`) into
 *    native/contracts/.
 * 2. scripts/generate_openapi_types.mjs merges them with the frozen tracked
 *    python-legacy contract into frontend/src/generated/openapi.json, renders
 *    openapi.ts and the native v2 request client nativeV2Client.ts.
 *
 * Usage: node scripts/generate_api_artifacts.mjs [--skip-rust]
 *   --skip-rust  reuse native/contracts/*.openapi.json already on disk (for
 *                example a CI artifact) and only run the Node generators.
 */
import {spawnSync} from 'node:child_process';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {main as generateTypes} from './generate_openapi_types.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const CONTRACTS_DIR = 'native/contracts';

/**
 * Contracts written by the `api_contracts` example. Must equal
 * `comicpile_roll_service::contract_artifacts::CONTRACT_ARTIFACTS`; the
 * generator fails when the Rust run writes a different set.
 */
export const GENERATED_CONTRACTS = [
  'bug-reports-v1.openapi.json',
  'issue-read-state-v1.openapi.json',
  'issue-v2.openapi.json',
  'preferences-v1.openapi.json',
  'reading-order-groups-v1.openapi.json',
  'roll-v1.openapi.json',
  'same-path-runtime.openapi.json',
  'thread-issues-v1.openapi.json',
  'thread-ordering-v1.openapi.json',
  'threads-v1.openapi.json',
  'threads-v2.openapi.json',
  'v2-runtime.openapi.json',
];

/** Every gitignored generated artifact path (repository-relative). */
export const GENERATED_ARTIFACT_PATHS = [
  'frontend/src/generated/nativeV2Client.ts',
  'frontend/src/generated/openapi.json',
  'frontend/src/generated/openapi.ts',
  ...GENERATED_CONTRACTS.map((name) => `${CONTRACTS_DIR}/${name}`),
  'docs/api/route-fragments/vercel-rewrites.json',
];

/**
 * Return the contract file names reported by the `api_contracts` example.
 *
 * @param {string} stdout - Example output (`wrote <path>` per file).
 * @returns {string[]} Sorted file names.
 */
export function writtenContracts(stdout) {
  return stdout
    .split('\n')
    .filter((line) => line.startsWith('wrote '))
    .map((line) => path.basename(line.slice('wrote '.length).trim()))
    .sort();
}

export const contractCommand = () => [
  'cargo',
  'run',
  '--locked',
  '--quiet',
  '-p',
  'comicpile-roll-service',
  '--example',
  'api_contracts',
  '--',
  CONTRACTS_DIR,
];

export function main(argv = process.argv.slice(2)) {
  let skipRust = false;
  for (const arg of argv) {
    if (arg === '--skip-rust') skipRust = true;
    else {
      console.error(`unknown argument: ${arg}`);
      return 2;
    }
  }
  if (!skipRust) {
    const [cmd, ...args] = contractCommand();
    const result = spawnSync(cmd, args, {cwd: ROOT, stdio: ['inherit', 'pipe', 'inherit'], encoding: 'utf8'});
    if (result.status !== 0) {
      console.error(`Rust contract generation failed (exit ${result.status ?? result.error})`);
      return 1;
    }
    process.stdout.write(result.stdout);
    const written = writtenContracts(result.stdout);
    if (JSON.stringify(written) !== JSON.stringify([...GENERATED_CONTRACTS].sort())) {
      console.error(
        'Rust CONTRACT_ARTIFACTS and GENERATED_CONTRACTS disagree:\n' +
          `  rust: ${written.join(', ')}\n  node: ${GENERATED_CONTRACTS.join(', ')}`,
      );
      return 1;
    }
  }
  return generateTypes([]);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exit(main());
}
